UPDATE WORK_LOG_PLATFORM_INCOME
SET expected_amount = #{expectedAmount},
    settlement_status = #{settlementStatus}
WHERE income_id = #{incomeId}

mapper.select:
SELECT income_id, log_id, platform_id, expected_amount, settlement_status
FROM WORK_LOG_PLATFORM_INCOME
WHERE log_id = #{logId}

SELECT wpi.income_id, wpi.log_id, wpi.platform_id, wpi.expected_amount, wpi.settlement_status
FROM WORK_LOG_PLATFORM_INCOME wpi
JOIN WORK_LOG wl ON wpi.log_id = wl.log_id
WHERE wl.job_id = #{jobId}
  AND wpi.platform_id = #{platformId}
  AND wl.status = 'CONFIRMED'
  AND wl.work_date IS NOT NULL
  AND wl.work_date BETWEEN #{startDate} AND #{endDate}

SELECT wpi.income_id, wpi.log_id, wpi.platform_id, wpi.expected_amount, wpi.settlement_status FROM WORK_LOG_PLATFORM_INCOME wpi JOIN WORK_LOG wl ON wpi.log_id = wl.log_id WHERE wl.user_id IN
#{userId}
AND wl.status = 'CONFIRMED' AND wl.work_date IS NOT NULL AND wl.work_date BETWEEN #{startDate} AND #{endDate}
